precision highp float;precision highp int;uniform mat4 modelViewMatrix;uniform mat4 projectionMatrix;in vec3 position;in vec2 uv;uniform vec4 sourceColor;uniform vec4 sourceUV;uniform vec4 _MainTex_ST;uniform vec4 _TintColor;
out highp vec4 vs_TEXCOORD1;
out highp vec4 vs_COLOR0;
void main(){vec2 pUV=uv*sourceUV.xy+sourceUV.zw;
vs_TEXCOORD1=vec4(pUV,0.,0.);
vs_COLOR0=sourceColor;
gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}

Effect/AddTop.fragment:
precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 1
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _MainColor;
uniform 	vec4 _MainTex_ST;
uniform mediump sampler2D _MainTex;
in highp vec4 vs_TEXCOORD1;
in highp vec4 vs_COLOR0;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
vec4 u_xlat1;
mediump vec4 u_xlat16_1;
vec4 u_xlat2;
vec2 u_xlat3;
void main()
{
    u_xlat0.w = _MainColor.w;
    u_xlat3.xy = vs_TEXCOORD1.xy * _MainTex_ST.xy + _MainTex_ST.zw;
    u_xlat16_1 = texture(_MainTex, u_xlat3.xy);
    u_xlat2.xyz = u_xlat16_1.xyz * _MainColor.xyz;
    u_xlat2.w = u_xlat16_1.w * u_xlat16_1.w;
    u_xlat0.x = u_xlat16_1.w;
    u_xlat0 = u_xlat0.xxxw * u_xlat2;
    u_xlat1.xyz = u_xlat0.xyz;
    u_xlat1.w = vs_COLOR0.w;
    u_xlat1 = u_xlat1 * vs_COLOR0.wwww;
    u_xlat0.xyz = vs_COLOR0.xyz;
    u_xlat0 = u_xlat0 * u_xlat1;
    u_xlat0 = u_xlat0 * _MainColor.wwww;
    u_xlat0 = u_xlat0 + u_xlat0;
    u_xlat0 = clamp(u_xlat0, 0.0, 1.0);
    SV_Target0 = u_xlat0;
    return;
}

